-- V86.44 — 10 أسئلة لكل تدريب.
-- الأسئلة مبنية على موضوعات الفيديوهات المثبتة من عناوينها ووصفها ومصادر التدريب المتاحة.
-- التدريب 3 غير مفهرس نصيًا في المصادر العامة؛ لذلك أسئلته هنا أسئلة فهم ومراجعة للمحتوى، وليست اقتباسًا مزعومًا من نص غير متاح.

do $$
declare a uuid;
begin
  -- 1
  select id into a from public.training_assessments where lesson_no=1;
  insert into public.training_questions(assessment_id,question_no,question,model_answer,rubric)
  values
  (a,1,'ما المقصود بالعمل بشكل احترافي في مشروع DXN، وما الفرق بين معرفة العمل وممارسة العمل؟','العمل الاحترافي يعني فهم أساسيات المشروع ثم تحويل المعرفة إلى خطوات عملية منتظمة، مع التعلم والتطبيق والمتابعة والتطوير المستمر.','يذكر الفكرة + يربط المعرفة بالتطبيق.'),
  (a,2,'لماذا ينبغي أن يتعلم العضو عن الشركة والمنتجات ونظام العمل قبل أن يبدأ بالتحدث مع الآخرين؟','حتى يتحدث بثقة ودقة، ويجيب عن الأسئلة الأساسية دون مبالغة أو معلومات غير موثوقة.','ذكر المعرفة والثقة والدقة.'),
  (a,3,'رتّب بصورة عملية أولويات العضو الجديد خلال مرحلة التأسيس.','التعلم، فهم المنتجات، فهم طريقة العمل، تجربة ما يناسبه، التدريب على العرض والمتابعة، ثم البدء بالتطبيق المنتظم.','ترتيب منطقي لا مجرد قائمة.'),
  (a,4,'ما أهمية تدوين المعلومات والخطوات بدل الاكتفاء بمشاهدة التدريب؟','التدوين يساعد على تثبيت المعلومات وتحويلها إلى مرجع يمكن مراجعته وتطبيقه.','سبب تعليمي عملي واضح.'),
  (a,5,'إذا شاهد عضو عدة تدريبات لكنه لم يطبق أي خطوة، فهل يمكن اعتبار أنه بدأ العمل احترافيًا؟ ولماذا؟','لا؛ المشاهدة مرحلة تعلم، أما العمل الاحترافي فيظهر عندما تتحول المعرفة إلى تطبيق ومتابعة ونتائج قابلة للمراجعة.','يفرق بين التعلم والتطبيق.'),
  (a,6,'كيف يستفيد العضو من قائد الفريق دون أن يعتمد عليه اعتمادًا كاملًا؟','يسأل ويستفيد من الخبرة والتوجيه، ثم يتعلم تنفيذ الخطوات بنفسه ويطور استقلاليته.','توازن بين الدعم والاستقلالية.'),
  (a,7,'ما الخطأ المهني في إعطاء معلومة عن منتج أو نظام وأنت غير متأكد منها؟','الخطأ هو التخمين أو تقديم المعلومة كحقيقة؛ الأفضل الرجوع إلى مصدر موثوق ثم الإجابة.','يذكر التحقق من المصدر.'),
  (a,8,'ضع مثالًا ليوم عمل منظم لعضو جديد يوازن بين التعلم والتطبيق.','وقت محدد للتعلم والمراجعة، ثم التواصل أو المتابعة وتسجيل النتائج، مع مراجعة ما تم إنجازه في نهاية اليوم.','وجود تعلم + تطبيق + متابعة + مراجعة.'),
  (a,9,'ما معنى الاستمرار في العمل بصورة مهنية عندما لا تظهر النتائج سريعًا؟','الاستمرار في تنفيذ الخطوات الصحيحة وقياس التقدم وتعديل الأخطاء بدل الحكم على المشروع من نتيجة قصيرة المدى.','يفرق بين الصبر والعمل العشوائي.'),
  (a,10,'اذكر ثلاثة مؤشرات تدل على أن العضو انتقل من مرحلة التعلم إلى مرحلة الممارسة.','يستطيع شرح الأساسيات، ينفذ خطوات العمل بنفسه، ويتابع النتائج ويصحح أخطاءه.','ثلاثة مؤشرات عملية.'),
  -- 2
  (a,1,'ما التصنيف العام لمنتجات DXN الذي يجب أن يعرفه العضو قبل الحديث عنها؟','ينبغي معرفة فئات المنتجات مثل المشروبات والمنتجات الغذائية والمكملات ومنتجات العناية الشخصية والبشرة وغيرها بحسب الكتالوج الرسمي.','تصنيف صحيح دون ادعاءات طبية.'),
  (a,2,'لماذا يجب أن يعرف العضو استخدام المنتج وطريقة استعماله قبل التوصية به؟','حتى يشرح الاستخدام بصورة صحيحة ويتجنب إعطاء تعليمات خاطئة أو مبالغات.','يربط المعرفة بالمسؤولية.'),
  (a,3,'ما الفرق بين شرح خصائص المنتج وبين الادعاء بأنه يعالج مرضًا؟','شرح الخصائص والاستخدامات المعلنة يختلف عن الادعاء الطبي بعلاج مرض؛ يجب الالتزام بالمعلومات الرسمية وعدم تقديم وعود علاجية.','تمييز واضح بين الوصف والادعاء الطبي.'),
  (a,4,'كيف تختار منتجًا مناسبًا لشخص يسأل عن منتجات DXN؟','أفهم حاجته أولًا ثم أشرح المنتجات ذات الصلة وفق المعلومات الرسمية وطريقة الاستخدام، وأحيله للمختص عند وجود سؤال طبي.','حاجة العميل + مصدر رسمي + إحالة عند الحاجة.'),
  (a,5,'لماذا تعد تجربة المنتج ومعرفة تفاصيله مهمة في التواصل المهني؟','لأنها تساعد العضو على فهم تجربة الاستخدام والحديث عن خصائص المنتج بوضوح دون نقل كلام غير متحقق منه.','يذكر الخبرة والمعرفة دون ادعاءات.'),
  (a,6,'كيف تتعامل مع سؤال عن فائدة صحية لا يملك العضو مصدرًا موثوقًا لها؟','لا يخمّن؛ يبحث في المصدر الرسمي أو يوجه الشخص إلى مختص مناسب إذا كان السؤال طبيًا.','رفض التخمين والرجوع لمصدر.'),
  (a,7,'ما المعلومات الأساسية التي يجب أن يعرفها العضو عن أي منتج قبل عرضه؟','اسم المنتج، فئته، مكوناته أو خصائصه المعلنة، طريقة الاستخدام، التحذيرات أو القيود، والسعر/التوفر وفق المصدر الرسمي.','أربع نقاط أو أكثر من القائمة.'),
  (a,8,'لماذا لا يكفي حفظ أسماء المنتجات دون فهمها؟','لأن العضو سيواجه أسئلة ومواقف مختلفة ويحتاج إلى فهم الاستخدام والخصائص وليس مجرد حفظ الاسم.','يفرق بين الحفظ والفهم.'),
  (a,9,'كيف تشرح منتجًا لشخص للمرة الأولى في أقل من دقيقة؟','أحدد احتياجه، أذكر الفئة والميزة الأساسية المعلنة، أوضح طريقة الاستخدام بإيجاز، ثم أسأل إن كان يريد تفاصيل أكثر.','شرح مختصر ومنظم.'),
  (a,10,'اذكر قاعدة مهنية واحدة يجب ألا يخالفها العضو عند الحديث عن المنتجات الصحية.','ألا يقدم تشخيصًا أو وعدًا بعلاج مرض، وأن يلتزم بالمعلومات الرسمية والاستخدام الصحيح.','قاعدة سلامة واضحة.'),
  -- 3
  (a,1,'بعد مشاهدة التدريب الثالث، ما الفكرة المركزية التي يطرحها المدرب؟','يجب أن يكتب العضو الفكرة المركزية كما فهمها من الفيديو، مع دليل أو مثال ورد في التدريب.','إجابة مرتبطة مباشرة بالفيديو.'),
  (a,2,'اذكر ثلاث نقاط رئيسية من التدريب الثالث ورتبها حسب أهميتها من وجهة نظرك.','إجابة مفتوحة؛ تقبل إذا كانت النقاط مستندة إلى محتوى الفيديو ومبررة.','ثلاث نقاط + تبرير.'),
  (a,3,'ما المفهوم الجديد الذي تعلمته من التدريب الثالث؟ اشرحه بأسلوبك.','إجابة مفتوحة مرتبطة بمحتوى الفيديو.','وضوح وفهم شخصي.'),
  (a,4,'اذكر مثالًا عمليًا قدمه المدرب أو استنتجه من التدريب، واشرح ماذا نتعلم منه.','إجابة مرتبطة بمثال حقيقي من الفيديو أو تطبيق مباشر لفكرته.','مثال + درس مستفاد.'),
  (a,5,'ما الخطأ أو السلوك الذي يحذر منه التدريب الثالث؟ وكيف تتجنبه؟','يذكر السلوك كما ورد أو استنتج بوضوح، ثم يذكر طريقة عملية لتجنبه.','تشخيص الخطأ + حل.'),
  (a,6,'كيف يمكن تحويل فكرة من التدريب الثالث إلى إجراء عملي هذا الأسبوع؟','يختار فكرة محددة ويحولها إلى خطوة قابلة للتنفيذ والقياس.','فكرة + إجراء + معيار نجاح.'),
  (a,7,'ما السؤال الذي ترى أن كل عضو يجب أن يطرحه على نفسه بعد هذا التدريب؟ ولماذا؟','إجابة مفتوحة بشرط ارتباط السؤال بهدف التدريب.','سؤال عميق مرتبط بالمحتوى.'),
  (a,8,'لو طلب منك تلخيص التدريب الثالث في 60 ثانية، ماذا ستقول؟','تلخيص مركز يذكر الفكرة الأساسية وأهم تطبيق.','اختصار دون خروج عن المحتوى.'),
  (a,9,'ما الفرق بين فهم فكرة التدريب الثالث وبين القدرة على تطبيقها؟','الفهم معرفة المعنى، والتطبيق تحويله إلى سلوك أو إجراء فعلي يمكن ملاحظته وقياسه.','تمييز واضح.'),
  (a,10,'اذكر خطوة واحدة ستبدأ بها مباشرة بعد اجتياز هذا التدريب.','خطوة عملية مرتبطة مباشرة بمحتوى التدريب.','قابلية التنفيذ.'),
  -- 4
  (a,1,'كيف تشرح لشخص جديد ما هو مشروع DXN بصورة مختصرة ومحايدة؟','هو مشروع يعتمد على منتجات الشركة ونظام تسويق مباشر متعدد المستويات، ويحتاج إلى تعلم وفهم النظام ثم تطبيق مهارات التسويق وبناء الفريق وفق القواعد المعتمدة.','تعريف متوازن دون وعود دخل.'),
  (a,2,'ما العناصر الأساسية التي ينبغي أن يفهمها العضو عن الشركة قبل البدء؟','الشركة ونشاطها، المنتجات، النظام التسويقي، طريقة العمل، والسياسات والمصادر الرسمية.','ذكر العناصر الأساسية.'),
  (a,3,'لماذا يجب عدم تقديم الدخل المالي على أنه مضمون أو سريع؟','لأن النتائج تعتمد على العمل والمهارة والاستمرارية والظروف، والوعود المضمونة أو المبالغ فيها غير مهنية.','يذكر عدم ضمان النتائج.'),
  (a,4,'كيف تفرق بين تعريف شخص بالمشروع وبين الضغط عليه للانضمام؟','التعريف يقدم المعلومات ويترك القرار للشخص، بينما الضغط يحاول إجباره أو استغلال اعتراضاته لاتخاذ قرار.','تمييز سلوكي واضح.'),
  (a,5,'ما دور المنتجات في فهم مشروع DXN؟','المنتج جزء أساسي من قيمة المشروع ومن عملية الاستهلاك والتوصية، لذلك يجب فهمه واستخدامه والتحدث عنه بدقة.','ربط المنتج بالنظام دون مبالغة.'),
  (a,6,'إذا قال شخص: لا أملك وقتًا، كيف يكون الرد المهني؟','أفهم ظروفه أولًا ثم أوضح أن العمل يحتاج وقتًا واقعيًا يمكن تنظيمه، دون وعود بنتائج من وقت محدود.','تعاطف + واقعية.'),
  (a,7,'إذا قال شخص: لا أفهم المشروع، ما أفضل خطوة؟','أعيد الشرح بصورة أبسط أو أرسل له التدريب المناسب وأتأكد من فهمه قبل الانتقال للخطوة التالية.','تبسيط + تحقق من الفهم.'),
  (a,8,'ما أهمية استخدام المصادر الرسمية عند شرح معلومات الشركة؟','لتقليل الأخطاء والشائعات وتقديم معلومات محدثة يمكن الرجوع إليها.','مصدر + دقة + تحديث.'),
  (a,9,'كيف تعرف أن الشخص فهم فكرة المشروع فعلًا؟','أطلب منه أن يشرح الفكرة بأسلوبه أو يجيب عن أسئلة أساسية بدل الاكتفاء بقوله نعم فهمت.','اختبار الفهم.'),
  (a,10,'ما أهم شيء يجب أن يتجنبه العضو عند تقديم المشروع لأول مرة؟','المبالغة والضغط والوعود المالية أو الصحية غير الموثقة.','ذكر واحد أو أكثر مع السبب.'),
  -- 5
  (a,1,'ما المقصود بالمتابعة الفعالة بعد عرض المشروع على شريك محتمل؟','هي التواصل المنظم بعد العرض لفهم موقف الشخص والإجابة عن أسئلته ومساعدته على اتخاذ قرار مناسب دون ضغط.','تعريف واضح.'),
  (a,2,'لماذا لا تعني المتابعة تكرار نفس الرسالة كل يوم؟','لأن المتابعة الجيدة تضيف قيمة وتبني على آخر تفاعل وتراعي توقيت الشخص واهتمامه.','قيمة + سياق + توقيت.'),
  (a,3,'ما أول سؤال مناسب في متابعة شخص شاهد العرض ولم يرد؟','سؤال مفتوح ومحترم مثل: ما أكثر نقطة لفتت انتباهك أو ما السؤال الذي بقي لديك؟','سؤال غير ضاغط.'),
  (a,4,'كيف تتعامل مع شخص قال: سأفكر؟','أحترم قراره، وأسأل إن كان هناك جانب يحتاج توضيحًا، وأتفق معه على وقت مناسب للعودة إن رغب.','احترام القرار + تحديد احتياج.'),
  (a,5,'كيف تميز بين الاعتراض الحقيقي وبين عدم الاهتمام؟','من خلال أسئلة توضيحية والاستماع؛ الاعتراض الحقيقي عادة يرتبط بنقطة محددة يمكن مناقشتها، بينما عدم الاهتمام قد يكون قرارًا نهائيًا.','استماع وتمييز.'),
  (a,6,'ما المعلومات التي يجب تسجيلها بعد كل متابعة؟','آخر تواصل، موقف الشخص، سؤاله أو اعتراضه، الخطوة التالية، وموعد المتابعة المتفق عليه إن وجد.','سجل عملي.'),
  (a,7,'ماذا تفعل إذا رفض الشخص الفرصة بوضوح؟','أحترم قراره وأنهي الحوار باحترام، وأترك الباب مفتوحًا دون إلحاح.','احترام وعدم ضغط.'),
  (a,8,'لماذا تعد المتابعة مهارة وليست مجرد اتصال؟','لأنها تحتاج استماعًا وفهمًا وتوقيتًا وأسئلة مناسبة وتقديم قيمة وتوثيقًا للخطوات.','عدة مهارات مترابطة.'),
  (a,9,'اكتب نموذج رسالة متابعة مهنية قصيرة بعد مشاهدة الفيديو.','مثال: ما رأيك بالفكرة بعد المشاهدة؟ هل هناك نقطة معينة تريد أن أوضحها لك؟','مختصرة وغير ضاغطة.'),
  (a,10,'متى تكون المتابعة غير مهنية؟','عندما تتحول إلى إزعاج أو ضغط أو تكرار بلا قيمة أو تجاهل واضح لرفض الشخص.','معيار سلوكي واضح.'),
  -- 6
  (a,1,'ما المقصود بالفريق الفعال في صناعة البيع المباشر؟','فريق يتعلم ويطبق ويتواصل ويتابع ويطور أفراده أنفسهم، وليس مجرد عدد من الأعضاء المسجلين.','يفرق بين العدد والفاعلية.'),
  (a,2,'لماذا لا يكفي تسجيل أعضاء جدد لبناء فريق قوي؟','لأن الفريق يحتاج تدريبًا ومتابعة وتطبيقًا وتحويل الأعضاء إلى أشخاص قادرين على العمل باستقلالية.','ذكر التدريب والمتابعة.'),
  (a,3,'ما الدور الحقيقي للقائد داخل الفريق؟','التوجيه والتعليم والدعم والمتابعة وبناء بيئة تساعد الأعضاء على التطور، وليس تنفيذ العمل بدلًا عنهم.','دور قيادي غير اتكالي.'),
  (a,4,'كيف تساعد العضو الجديد على الانتقال من الحماس إلى العمل المنظم؟','أعطيه خطوات صغيرة واضحة، تدريبًا مناسبًا، موعد متابعة، ومؤشرات بسيطة للإنجاز.','خطة عملية.'),
  (a,5,'ما أثر البيئة الإيجابية في استمرارية الفريق؟','تزيد التعلم والتعاون والثقة وتقلل الانقطاع عندما يواجه العضو صعوبة.','أثر واضح.'),
  (a,6,'كيف تتعامل مع عضو لا ينفذ ما تم الاتفاق عليه؟','أفهم السبب أولًا، ثم أحدد خطوة بسيطة وموعدًا واضحًا وأتابع التنفيذ بدل اللوم المستمر.','تشخيص + اتفاق + متابعة.'),
  (a,7,'ما الفرق بين قيادة الفريق والسيطرة عليه؟','القيادة تطور قدرة الأعضاء وتوجههم، أما السيطرة فتعتمد على الأوامر والضغط وتقليل استقلالية العضو.','تمييز واضح.'),
  (a,8,'كيف تقيس فعالية فريقك بعيدًا عن عدد الأعضاء فقط؟','من خلال التدريب، النشاط، التطبيق، المتابعة، الإنجاز، ونمو الأعضاء في القدرة على العمل.','مؤشرات متعددة.'),
  (a,9,'لماذا يجب أن يتعلم القائد نفسه باستمرار؟','لأن تطوير القائد يرفع جودة التوجيه ويجعله قادرًا على حل مشكلات جديدة وتحديث معرفته.','التعلم المستمر.'),
  (a,10,'اذكر ثلاث صفات يحتاجها القائد لبناء فريق مستقر.','الاستماع، الصبر، الوضوح، المتابعة، والقدرة على التعليم؛ يذكر أي ثلاث مع شرح مختصر.','ثلاث صفات + معنى.'),
  -- 7
  (a,1,'ما المقصود بإقفال الدائرة في العمل اليومي؟','إكمال سلسلة العمل من التعلم والعرض والتواصل والمتابعة إلى الخطوة التالية بدل ترك الفرص معلقة.','فهم مفهوم الدائرة.'),
  (a,2,'ما أهم المهام اليومية التي ينبغي أن يراجعها العضو؟','التعلم، التواصل، العرض، المتابعة، خدمة العملاء/الفريق، وتسجيل النتائج بحسب خطته.','عدة مهام مترابطة.'),
  (a,3,'لماذا يجب أن تكون المهام اليومية قابلة للقياس؟','حتى يعرف العضو ما أنجزه وما يحتاج إلى تحسين بدل الاعتماد على الشعور فقط.','القياس والمتابعة.'),
  (a,4,'ما الفرق بين الانشغال وبين النشاط المنتج؟','الانشغال قد يستهلك الوقت دون تقدم، بينما النشاط المنتج مرتبط بخطوة تخدم الهدف ويمكن قياسها.','تمييز عملي.'),
  (a,5,'إذا لم يكن لديك وقت طويل، كيف تحافظ على دائرة العمل؟','أحدد أهم المهام وأخصص لها وقتًا ثابتًا واقعيًا، وأركز على الاستمرارية بدل محاولة إنجاز كل شيء دفعة واحدة.','أولوية + وقت + استمرارية.'),
  (a,6,'ما أهمية تسجيل نتائج التواصل والمتابعة اليومية؟','لمنع النسيان، ومعرفة حالة كل شخص، وتحديد الخطوة التالية.','توثيق.'),
  (a,7,'ماذا تفعل في نهاية يوم العمل إذا بقيت فرص كثيرة دون متابعة؟','أصنفها حسب الأولوية وأحدد مواعيد واضحة للمتابعة بدل التواصل العشوائي.','ترتيب أولويات.'),
  (a,8,'كيف تمنع نفسك من قضاء اليوم كله في التدريب دون تطبيق؟','أحدد نسبة أو وقتًا للتعلم ثم أنتقل إلى التطبيق وأقيس التنفيذ.','توازن تعلم/تطبيق.'),
  (a,9,'ما المؤشر الذي يخبرك أن يومك كان منتجًا؟','وجود خطوات عملية مكتملة ونتائج أو بيانات جديدة يمكن البناء عليها في اليوم التالي.','نتيجة قابلة للملاحظة.'),
  (a,10,'ضع قائمة مختصرة من خمس مهام يومية مناسبة لعضو نشط.','تعلم، تواصل جديد، عرض، متابعة، تسجيل النتائج وتحديد خطة الغد.','خمس مهام عملية.'),
  -- 8
  (a,1,'ما المقصود بمقدمات بناء الفريق الفعال؟','هي المبادئ والقناعات والخطوات الأولية التي تهيئ العضو والقائد لبناء فريق على أساس صحيح.','تعريف واضح.'),
  (a,2,'لماذا تبدأ عملية بناء الفريق من القائد نفسه؟','لأن سلوك القائد وعاداته وطريقة تعامله تصبح نموذجًا يتعلم منه أعضاء الفريق.','القدوة.'),
  (a,3,'ما أهمية وضوح الهدف قبل دعوة الآخرين إلى الفريق؟','يساعد العضو على معرفة سبب عمله وما الذي يريد تحقيقه، ويجعل تواصله أكثر وضوحًا.','هدف + وضوح.'),
  (a,4,'كيف تشرح الفرصة دون أن تجعل هدفك إقناع الجميع؟','أقدم الفكرة بوضوح، أجيب عن الأسئلة، وأترك للشخص حرية اتخاذ القرار وأركز على الأشخاص المناسبين.','احترام القرار.'),
  (a,5,'ما معنى البحث عن الأشخاص المناسبين للفريق؟','البحث عن أشخاص لديهم اهتمام أو احتياج واستعداد للتعلم والعمل، بدل محاولة إجبار أي شخص على الانضمام.','ملاءمة لا ضغط.'),
  (a,6,'كيف تتعامل مع الرفض في بداية بناء الفريق؟','أعتبره قرارًا شخصيًا، أتعلم من التجربة وأستمر في التواصل مع أشخاص آخرين دون جدال أو إساءة.','نضج واستمرارية.'),
  (a,7,'ما العلاقة بين التدريب وبناء الفريق؟','التدريب يحول العضو من شخص مسجل إلى شخص يفهم العمل ويستطيع تطبيقه وتكراره مع الآخرين.','التدريب والتكرار.'),
  (a,8,'لماذا يجب أن تكون توقعات العضو الجديد واقعية؟','حتى يفهم أن بناء المهارة والنتائج يحتاج وقتًا وتعلمًا وتطبيقًا، ولا يبني قراراته على وعود غير واقعية.','واقعية التوقعات.'),
  (a,9,'كيف تجعل عضوًا جديدًا يشعر أنه شريك وليس تابعًا؟','أشركه في التعلم واتخاذ خطواته، أحترم رأيه، وأدعمه ليصبح قادرًا على العمل بنفسه.','شراكة واستقلالية.'),
  (a,10,'ما أول ثلاثة أمور ستفعلها مع عضو جديد خلال أسبوعه الأول؟','أحدد له مسار التعلم، أساعده على فهم الأساسيات، ثم أضع معه أول تطبيق ومتابعة قصيرة.','تعلم + تطبيق + متابعة.');
end $$;
